    r.path.startsWith(QA+'/') && r.pin && JSON.stringify(Object.keys(r.pin).sort()) === '["bytes","sha256"]' &&
    Number.isSafeInteger(r.pin.bytes) && r.pin.bytes > 0 && /^[0-9a-f]{64}$/.test(r.pin.sha256),'external directory permission reference');
  const rows = [];
